export const getCreateSessionUrl = () => {




  return `/session`
}

/**
 * This API issues a new JWT token for logging in from the Everest API.
The provided user must have the `login` capability.

 * @summary Everest API Login
 */
export const createSession = async (userCredentials: UserCredentials, options?: RequestInit): Promise<createSessionResponse> => {

  return playwrightFetcher<createSessionResponse>(getCreateSessionUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(userCredentials)
  }
);}



